  public JSONArray history(String id)throws Exception{return history(id,0);}
  public JSONArray history(String id,int offset)throws Exception{return query("SELECT data FROM versions WHERE memory_id=? ORDER BY created DESC,rowid DESC LIMIT 100 OFFSET ?",id,""+Math.max(0,offset));}
  public JSONArray conflicts()throws Exception{return query("SELECT data FROM conflicts WHERE state='open' ORDER BY created DESC LIMIT 100");}
