    if(matching.length()>1){JSONObject focused=null;int count=0;for(int i=0;i<matching.length();i++)if(context.contains(matching.getJSONObject(i).getString("id"))){focused=matching.getJSONObject(i);count++;}if(count==1)return new JSONObject().put("entity",focused).put("state","resolved").put("basis","最近明确上下文中的唯一同名对象").put("assumed",true);return unresolved(name,matching);}
