  private static JSONObject unresolved(String name,JSONArray choices)throws Exception {JSONArray ids=new JSONArray();for(int i=0;i<choices.length();i++)add(ids,choices.getJSONObject(i).optString("id"));return new JSONObject().put("state","unresolved").put("label",name).put("candidates",ids);}
