  private JSONObject continueReminder(JSONObject proposed,JSONObject source)throws Exception {JSONObject request=proposed.optJSONObject("reminder");if(request==null||request.optString("referenceId").isEmpty())return null;JSONObject t=TimeAnchor.reminder(request,source,store);if(!t.optBoolean("linkedContinuation"))return null;JSONObject r=store.one("memories",t.getString("referencedMemoryId"));if(r==null)return null;JSONArray sources=array(r,"sourceIds");add(sources,source.getString("id"));r.put("sourceIds",sources).put("reminderTime",t).put("reminderRequested",true).put("careSourceId",source.getString("id")).put("updated",System.currentTimeMillis()).put("lastChangeSourceId",source.getString("id")).put("changeReason","按这轮补充的时刻继续安排提醒，保留原日期和两轮原话");r.remove("remindAt");r.remove("reminderConfirmed");r.remove("reminderFired");r.remove("careDeferred");r.remove("careDeferredSourceId");if(TimeAnchor.resolved(t)){JSONObject time=new JSONObject(t.toString()).put("raw",t.optString("dateRaw",t.optString("raw"))).put("clockRaw",t.optString("raw"));r.put("time",time);if(t.optString("precision").equals("minute")&&t.optLong("start")>System.currentTimeMillis())r.put("remindAt",t.getLong("start"));}store.put("memories",r);return r;}
  private JSONArray peers(JSONObject r)throws Exception{return r.optString("factKey").isEmpty()?new JSONArray():query("SELECT data FROM memories WHERE fact_key=? AND truth_state IN ('current','disputed') AND id<>? ORDER BY created ASC",r.getString("factKey"),r.getString("id"));}
