      LinkedHashSet<String> explicit=new LinkedHashSet<>();boolean uncertainName=false;if(!intent.equals("query"))for(int i=0;i<Math.min(100,incoming.length());i++){JSONObject p=incoming.getJSONObject(i);JSONArray mentions=new JSONArray();if(p.optJSONObject("subject")!=null)mentions.put(p.getJSONObject("subject"));JSONArray others=array(p,"relatedEntities");for(int j=0;j<others.length();j++)mentions.put(others.get(j));for(int j=0;j<mentions.length();j++){JSONObject mention=mentions.getJSONObject(j);if(mention.optBoolean("pronoun")||mention.optString("name").matches("(他|她|它|他们|她们|那家店|那个人|那位|这家店|这位|那里|那个|这个)"))continue;JSONObject resolved=resolveSubject(mention,source,context);if(resolved.has("entity"))explicit.add(resolved.getJSONObject("entity").getString("id"));else uncertainName=true;}}if(!explicit.isEmpty()||uncertainName)context=explicit;
