    boolean validQuote=source.optString("content").contains(quote)&&!quote.trim().isEmpty();boolean valid=mode.equals("correction")&&quote.matches("(?s).*(记错|说错|更正|不是|纠正|写错).*")||mode.equals("change")&&quote.matches("(?s).*(现在|从今天|改为|变成|不再|开始|改了|改喝|换成).*");
