    String title=target.optString("title");int titleAt=ChatMemoryEdit.wholeValueIndex(title,oldValue,0);if(titleAt>=0&&ChatMemoryEdit.wholeValueIndex(title,oldValue,titleAt+oldValue.length())<0)next.put("title",title.substring(0,titleAt)+value+title.substring(titleAt+oldValue.length()));
